# Shared helpers for the Java audit fact sheets: comment/string stripping and brace matching.
# Regex-based on purpose (no parser dependency); every heuristic yields candidates, never verdicts.
import os
import re


def strip_java(src):
    """Blank out comments, string/char literals and text blocks, keeping offsets and newlines."""
    out = list(src)
    i, n = 0, len(src)

    def blank(a, b):
        for k in range(a, b):
            if out[k] != '\n':
                out[k] = ' '

    while i < n:
        c = src[i]
        if src.startswith('//', i):
            j = src.find('\n', i)
            j = n if j < 0 else j
            blank(i, j)
            i = j
        elif src.startswith('/*', i):
            j = src.find('*/', i + 2)
            j = n if j < 0 else j + 2
            blank(i, j)
            i = j
        elif src.startswith('"""', i):
            j = src.find('"""', i + 3)
            j = n if j < 0 else j + 3
            blank(i + 1, j - 1)
            i = j
        elif c == '"' or c == "'":
            j = i + 1
            while j < n and src[j] != c and src[j] != '\n':
                j += 2 if src[j] == '\\' else 1
            j = min(j + 1, n)
            blank(i + 1, j - 1)
            i = j
        else:
            i += 1
    return ''.join(out)


def match_brace(s, open_idx):
    """Index of the brace closing the one at open_idx, or len(s)."""
    depth = 0
    for k in range(open_idx, len(s)):
        ch = s[k]
        if ch == '{':
            depth += 1
        elif ch == '}':
            depth -= 1
            if depth == 0:
                return k
    return len(s)


def match_paren(s, open_idx):
    depth = 0
    for k in range(open_idx, len(s)):
        ch = s[k]
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth == 0:
                return k
    return len(s)


def line_of(s, idx):
    return s.count('\n', 0, idx) + 1


MODIFIERS = r'(?:(?:public|protected|private|static|final|synchronized|abstract|native|default|strictfp)\s+)*'
METHOD_RE = re.compile(
    r'(?P<annos>(?:@\w+(?:\.\w+)*(?:\([^()]*(?:\([^()]*\)[^()]*)*\))?\s+)*)'
    r'(?P<mods>' + MODIFIERS + r')'
    r'(?:<[^<>]*(?:<[^<>]*>[^<>]*)*>\s+)?'
    r'(?P<ret>[\w.$]+(?:<[^;{}()]*?>)?(?:\[\])*)\s+'
    r'(?P<name>[a-zA-Z_$][\w$]*)\s*\((?P<params>[^;{}()]*(?:\([^()]*\)[^;{}()]*)*)\)\s*'
    r'(?:throws\s+[\w.$,\s]+)?\{')
CTOR_KEYWORDS = {'if', 'for', 'while', 'switch', 'catch', 'synchronized', 'return', 'new', 'else', 'try', 'do'}


def methods(stripped):
    """Method declarations with body span: dicts name/mods/annos/params/start/end/line."""
    found = []
    for m in METHOD_RE.finditer(stripped):
        name = m.group('name')
        if name in CTOR_KEYWORDS or m.group('ret') in CTOR_KEYWORDS:
            continue
        body_open = m.end() - 1
        found.append({
            'name': name,
            'mods': m.group('mods').split(),
            'annos': m.group('annos'),
            'params': m.group('params').strip(),
            'ret': m.group('ret'),
            'start': body_open,
            'end': match_brace(stripped, body_open),
            'line': line_of(stripped, m.start('name')),
        })
    return found


def java_files(root):
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = sorted(d for d in dirnames if d not in ('build', 'node_modules') and not d.startswith(('.', 'target')))
        for f in sorted(filenames):
            if f.endswith('.java'):
                yield os.path.join(dirpath, f)


def java_version(base):
    """(version, source) from Maven or Gradle build files, or (None, reason)."""
    pats = [
        (r'<maven\.compiler\.release>\s*(\d+)', 'maven.compiler.release'),
        (r'<java\.version>\s*(\d+)', 'java.version'),
        (r'<release>\s*(\d+)\s*</release>', 'compiler release'),
        (r'<maven\.compiler\.source>\s*(?:1\.)?(\d+)', 'maven.compiler.source'),
        (r'JavaLanguageVersion\.of\(\s*(\d+)', 'gradle toolchain'),
        (r'sourceCompatibility\s*=\s*[\'"]?(?:JavaVersion\.VERSION_)?(?:1[._])?(\d+)', 'gradle sourceCompatibility'),
    ]
    for dirpath, dirnames, filenames in os.walk(base):
        dirnames[:] = [d for d in dirnames if d not in ('build', 'node_modules') and not d.startswith(('.', 'target'))]
        if dirpath.count(os.sep) - base.count(os.sep) > 2:
            dirnames[:] = []
        for f in ('pom.xml', 'build.gradle', 'build.gradle.kts'):
            if f in filenames:
                try:
                    text = open(os.path.join(dirpath, f), encoding='utf-8', errors='replace').read()
                except OSError:
                    continue
                for pat, label in pats:
                    m = re.search(pat, text)
                    if m:
                        return int(m.group(1)), os.path.relpath(os.path.join(dirpath, f), base) + ' ' + label
    return None, 'no pom.xml/build.gradle with a Java version found'


class Sheet:
    """Collects TREFFER lines per kind with a cap, then prints FAKT counts and the hits."""

    def __init__(self, cap):
        self.cap = cap
        self.hits = {}

    def hit(self, kind, text):
        self.hits.setdefault(kind, []).append(text)

    def count(self, kind):
        return len(self.hits.get(kind, []))

    def emit(self, kinds):
        for kind in kinds:
            rows = self.hits.get(kind, [])
            print('FAKT %s_count: %d' % (kind, len(rows)))
        print('')
        for kind in kinds:
            rows = self.hits.get(kind, [])
            for r in rows[:self.cap]:
                print('TREFFER %s: %s' % (kind, r))
            if len(rows) > self.cap:
                print('# %d more %s hits not listed' % (len(rows) - self.cap, kind))


# Fact sheet for the Java REST API contract audit. Usage: api_facts.py <repo-root> <source-dir>
import os
import re
import sys


MAPPING = re.compile(r'@(Get|Post|Put|Delete|Patch|Request)Mapping\b(?:\s*\(((?:[^()]|\([^()]*\))*)\))?')
WRITE_NAME = re.compile(r'^(create|delete|update|save|remove|add|execute|run|start|stop|trigger|reset|cancel|approve|import|install|apply)')
READ_NAME = re.compile(r'^(get|list|find|load|fetch|show)(?!.*(?:And|Or)(?:Create|Save))')


def mapping_paths(args, raw_args):
    """Paths of a mapping annotation, read from the raw text (string literals are blanked in the stripped one)."""
    if not raw_args:
        return ['']
    paths = re.findall(r'"([^"]*)"', raw_args)
    named = re.search(r'\b(?:value|path)\s*=\s*\{?([^}]*)\}?', raw_args)
    if named:
        paths = re.findall(r'"([^"]*)"', named.group(1)) or paths
    elif re.search(r'\b\w+\s*=', raw_args) and not raw_args.strip().startswith('"'):
        paths = []
    return paths or ['']


def main():
    base = os.path.abspath(sys.argv[1])
    src_root = os.path.join(base, sys.argv[2])
    sheet = Sheet(cap=40)
    files = controllers = handlers = handlers_doc = advice = 0
    entity_names = set()
    sources = []

    print('## FAKTENBLATT')
    print('# Measured deterministically (regex over the source, comments and strings removed).')
    print('# TREFFER lines are candidates with a location, not proof; check each one in the source.')
    print('')
    if not os.path.isdir(src_root):
        print('NICHT GEMESSEN: java_files_scanned (source directory %s missing)' % sys.argv[2])
        return

    for path in java_files(src_root):
        try:
            raw = open(path, encoding='utf-8', errors='replace').read()
        except OSError:
            continue
        files += 1
        s = strip_java(raw)
        if re.search(r'@Entity\b', s):
            m = re.search(r'\bclass\s+(\w+)', s)
            if m:
                entity_names.add(m.group(1))
        if re.search(r'@(RestController|Controller)\b', s):
            sources.append((path, raw, s))
        if re.search(r'@(ControllerAdvice|RestControllerAdvice)\b', s):
            advice += 1

    entity_re = re.compile(r'\b(%s)\b' % '|'.join(sorted(entity_names))) if entity_names else None

    for path, raw, s in sources:
        rel = os.path.relpath(path, base)
        controllers += 1
        cls = re.search(r'\bclass\s+\w+', s)
        head = s[:cls.start()] if cls else ''
        base_m = MAPPING.search(head)
        base_paths = mapping_paths(None, raw[base_m.start(2):base_m.end(2)] if base_m and base_m.group(2) is not None else None) if base_m else ['']
        for m in methods(s):
            mm = MAPPING.search(m['annos'])
            if not mm:
                continue
            handlers += 1
            anno_start = s.find(m['annos'].strip()[:20], max(0, m['start'] - len(m['annos']) - 400)) if m['annos'].strip() else -1
            verb = mm.group(1).upper()
            raw_args = None
            if mm.group(2) is not None and anno_start >= 0:
                a = s.find(mm.group(0), anno_start)
                if a >= 0:
                    raw_args = raw[a + len('@%sMapping' % mm.group(1)):a + len(mm.group(0))].strip()[1:-1]
            if verb == 'REQUEST':
                vm = re.search(r'RequestMethod\.(\w+)', mm.group(2) or '')
                verb = vm.group(1) if vm else 'ANY'
            paths = [b + p for b in base_paths for p in mapping_paths(None, raw_args)]
            where = '%s:%d %s %s %s()' % (rel, m['line'], verb, paths[0] or '/', m['name'])

            # Javadoc directly above the annotations (raw text, comments are blanked in s)
            before = raw[max(0, anno_start - 400):anno_start] if anno_start >= 0 else ''
            if re.search(r'\*/\s*$', before):
                handlers_doc += 1
            else:
                sheet.hit('handler_without_javadoc', where)

            ret = m['ret']
            params = m['params']
            if entity_re:
                ent_ret = entity_re.search(ret)
                ent_body = re.search(r'@RequestBody\s+(?:@\w+\s+)*([\w<>, ]+?)\s+\w+\s*(?:,|$)', params)
                if ent_ret:
                    sheet.hit('entity_exposed', '%s returns entity %s' % (where, ent_ret.group(1)))
                if ent_body and entity_re.search(ent_body.group(1)):
                    sheet.hit('entity_exposed', '%s takes entity %s as @RequestBody' % (where, entity_re.search(ent_body.group(1)).group(1)))
            if verb == 'GET' and WRITE_NAME.match(m['name']):
                sheet.hit('verb_mismatch', '%s: GET, name suggests a change' % where)
            if verb in ('POST', 'PUT', 'PATCH', 'DELETE') and READ_NAME.match(m['name']) and not re.search(r'search|query|preview|validate|analy', m['name'], re.I):
                sheet.hit('verb_mismatch', '%s: %s, name suggests a read' % (where, verb))
            if verb == 'POST' and re.match(r'^(create|add|register|import)', m['name']) \
                    and 'ResponseEntity' not in ret and not re.search(r'@ResponseStatus\s*\(\s*(?:code\s*=\s*|value\s*=\s*)?HttpStatus\.CREATED', m['annos']):
                sheet.hit('post_without_created', '%s answers 200 instead of 201' % where)
            if re.search(r'@RequestBody\b', params) and not re.search(r'@(Valid|Validated)\b', params) \
                    and not re.search(r'@RequestBody\s+(?:@\w+\s+)*(String|byte\[\]|Map<|JsonNode|List<String>)', params):
                sheet.hit('request_body_unvalidated', where)
            if re.search(r'\bMap\s*<\s*String\s*,\s*(Object|\?)\s*>', ret) or re.search(r'\b(JsonNode|ObjectNode|Object)\s*$', ret.strip()) or ret.strip() == 'Object':
                sheet.hit('untyped_response', '%s -> %s' % (where, re.sub(r'\s+', ' ', ret)))
            for p in paths:
                seg = [x for x in p.split('/') if x and not x.startswith('{')]
                bad = [x for x in seg if re.search(r'[A-Z_]', x)]
                if bad:
                    sheet.hit('path_style', '%s: segment %s not kebab-case' % (where, bad[0]))
                    break

    print('FAKT java_files_scanned: %d' % files)
    print('FAKT controllers: %d' % controllers)
    print('FAKT handlers: %d' % handlers)
    print('FAKT handlers_with_javadoc: %d' % handlers_doc)
    print('FAKT exception_advice_classes: %d' % advice)
    print('FAKT entity_types: %d' % len(entity_names))
    kinds = ['entity_exposed', 'verb_mismatch', 'post_without_created', 'request_body_unvalidated', 'untyped_response',
             'path_style', 'handler_without_javadoc']
    sheet.emit(kinds)
    print('')
    print('## PFLICHTFELDER')
    print('PFLICHT-FAKTEN: java_files_scanned controllers handlers')


if __name__ == '__main__':
    main()
PYEOF
